import pandas as pd

def run(inputs: dict) -> dict:
    events = inputs["app_events"].copy()

    # Ensure proper dtypes
    events["event_ts"] = pd.to_datetime(events["event_ts"])
    events = events.sort_values(by=["user_id", "event_ts", "event_id"], kind="mergesort")

    activity_types = {"view", "click", "logout"}

    result_rows = []

    for user_id, group in events.groupby("user_id", sort=False):
        session_open = False
        session_num = 0
        session_start = None
        session_end = None
        last_activity_ts = None
        event_count = 0
        heartbeat_count = 0

        def close_session():
            result_rows.append({
                "user_id": user_id,
                "session_num": session_num,
                "session_start": session_start,
                "session_end": session_end,
                "event_count": event_count,
                "heartbeat_count": heartbeat_count,
            })

        for _, row in group.iterrows():
            etype = row["event_type"]
            ts = row["event_ts"]

            if etype in activity_types:
                starts_new = False
                if not session_open:
                    starts_new = True
                else:
                    delta = ts - last_activity_ts
                    if delta > pd.Timedelta(minutes=30):
                        starts_new = True

                if starts_new:
                    if session_open:
                        close_session()
                    session_num += 1
                    session_start = ts
                    session_end = ts
                    event_count = 1
                    heartbeat_count = 0
                    last_activity_ts = ts
                    session_open = True
                else:
                    event_count += 1
                    session_end = ts
                    last_activity_ts = ts

                if etype == "logout":
                    close_session()
                    session_open = False

            else:  # heartbeat
                if session_open:
                    delta = ts - last_activity_ts
                    if delta <= pd.Timedelta(minutes=30):
                        event_count += 1
                        heartbeat_count += 1
                    # else dropped
                # else dropped

        if session_open:
            close_session()

    columns = ["user_id", "session_num", "session_start", "session_end",
               "event_count", "heartbeat_count"]

    if result_rows:
        user_sessions = pd.DataFrame(result_rows, columns=columns)
    else:
        user_sessions = pd.DataFrame(columns=columns)

    return {"user_sessions": user_sessions}
